import {NRF52_BOARDS} from './nrf52-boards.js';
import {crc32} from './project-zip.js';
export function packNRF52Image(bytes,id){const a=new Uint8Array(80+bytes.length),v=new DataView(a.buffer);a.set(new TextEncoder().encode('CFNRF52\0'));a.set(new TextEncoder().encode(id),8);v.setUint32(64,bytes.length,true);v.setUint32(68,crc32(bytes),true);a.set(bytes,80);validateNRF52Image(a,id);return a;}
export function validateNRF52Image(a,id){if(!NRF52_BOARDS[id]||!(a instanceof Uint8Array)||a.length<88)throw Error('nRF52 firmware hedefi/başlığı geçersiz.');const v=new DataView(a.buffer,a.byteOffset,a.byteLength),d=new TextDecoder(),b=a.subarray(80);if(d.decode(a.subarray(0,8))!=='CFNRF52\0'||d.decode(a.subarray(8,64)).replace(/\0.*$/s,'')!==id||a.subarray(72,80).some(x=>x)||v.getUint32(64,true)!==b.length||b.length>1048576||v.getUint32(68,true)!==crc32(b))throw Error('nRF52 firmware hedefi/boyutu/CRC geçersiz.');if(v.getUint32(80,true)!==0x20040000||!(v.getUint32(84,true)&1)||v.getUint32(84,true)<8||v.getUint32(84,true)>=b.length)throw Error('nRF52840 reset vektörü geçersiz.');return b;}
